(async () => {
  const targets = await getJson('http://127.0.0.1:8081/json');
  const target = targets.find((t) => String(t.title).includes('healspass')) || targets[0];
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.on('open', resolve); ws.on('error', reject); });
  let id = 1;
  const pending = new Map();
  const send = (method, params={}) => {
    const thisId = id++;
    ws.send(JSON.stringify({ id: thisId, method, params }));
    return new Promise((resolve) => pending.set(thisId, resolve));
  };
  const logs = [];
  ws.on('message', (data) => {
    const msg = JSON.parse(data.toString());
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); return; }
    if (msg.method === 'Runtime.consoleAPICalled') {
      const text = (msg.params.args||[]).map(a => a.value ?? a.description ?? a.type).join(' ');
      logs.push({kind:'console', type: msg.params.type, text: String(text).slice(0,400)});
    }
    if (msg.method === 'Runtime.exceptionThrown') {
      const desc = msg.params.exceptionDetails?.exception?.description || msg.params.exceptionDetails?.text;
      logs.push({kind:'exception', text: String(desc).slice(0,800)});
    }
  });
